CREATE TABLE IF NOT EXISTS public.affiliate_payouts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, affiliate_id uuid NOT NULL REFERENCES public.affiliates(id) ON DELETE RESTRICT, amount numeric NOT NULL CHECK (amount > 0), payment_method text NOT NULL, payment_reference text, status text NOT NULL DEFAULT 'PAID', paid_at timestamptz NOT NULL DEFAULT now(), paid_by uuid, notes text);